package com.manishrawat.realestate.servlet; import com.manishrawat.realestate.service.AuthService; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.*;
@WebServlet("/register") public class RegisterServlet extends HttpServlet {protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{try{new AuthService().register(r.getParameter("name"),r.getParameter("email"),r.getParameter("password"),r.getParameter("phone"));s.sendRedirect(r.getContextPath()+"/?registered=1");}catch(Exception e){throw new IOException(e);}}}
